namespace DiTichVietNam.Web.Services.Provinces;

public class ProvinceShape
{
    public string Slug { get; init; } = string.Empty;
    public string Name { get; init; } = string.Empty;
    public string PathData { get; init; } = string.Empty;
    public double LabelX { get; init; }
    public double LabelY { get; init; }
}

public record MapPoint(double X, double Y);

public class ArchipelagoShape
{
    public string Key { get; init; } = string.Empty;
    public string Name { get; init; } = string.Empty;
    public string ProvinceSlug { get; init; } = string.Empty;
    public IReadOnlyList<MapPoint> Islets { get; init; } = Array.Empty<MapPoint>();
    public double LabelX { get; init; }
    public double LabelY { get; init; }
    public bool LabelAnchorEnd { get; init; }
}

public class IslandShape
{
    public string Name { get; init; } = string.Empty;
    public string ProvinceSlug { get; init; } = string.Empty;
    public double X { get; init; }
    public double Y { get; init; }
    public bool ShowMarker { get; init; }
    public bool ShowLabel { get; init; }
    public string LabelText { get; init; } = string.Empty;
    public double LabelOffsetY { get; init; }
}

